import java.util.Arrays;

public class CopyCompareDemo {
    public static void main(String[] args) {
        // 1. The Reference Trap
        int[] original = {10, 20, 30};
        int[] alias = original; // Shared address!
        alias[0] = 99;
        System.out.println("original[0] after alias update: " + original[0]); // 99!

        // 2. Genuine Independent Copy
        int[] source = {1, 2, 3};
        int[] trueCopy = Arrays.copyOf(source, source.length);
        trueCopy[0] = 500;
        System.out.println("source[0] after trueCopy update: " + source[0]); // 1 (Safe!)

        // 3. Equality Comparison
        int[] a1 = {4, 5, 6};
        int[] a2 = {4, 5, 6};
        System.out.println("a1 == a2 (Address equality): " + (a1 == a2)); // false
        System.out.println("Arrays.equals(a1, a2) (Content equality): " + Arrays.equals(a1, a2)); // true
    }
}

