public class Main {
    public static void main(String[] args) {
        int[] src = {5, 10, 15};
        int[] dest = new int[src.length];
        for (int i = 0; i < src.length; i++) {
            dest[i] = src[i];
        }
        dest[0] = 99;
        System.out.println("src[0]=" + src[0] + ", dest[0]=" + dest[0]);
    }
}

