import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] full = {10, 20, 30, 40, 50, 60};
        int[] sub = Arrays.copyOfRange(full, 1, 4);
        for (int x : sub) {
            System.out.print(x + " ");
        }
        System.out.println();
    }
}

