practiceProblems.solutionCode:
import java.util.Arrays;

public class Main {
    public static int[] expandCapacity(int[] arr, int newCapacity) {
        return Arrays.copyOf(arr, newCapacity);
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3};
        arr = expandCapacity(arr, 5);
        arr[3] = 4;
        arr[4] = 5;
        System.out.println("New Length: " + arr.length + " | Last Element: " + arr[arr.length - 1]);
    }
}
